command_line:
set +e
cat > tiny.wdl <<'EOF'
version 1.0
workflow tiny {
  call hello
  output { String msg = hello.msg }
}
task hello {
  command <<<
    echo hello > out.txt
  >>>
  output { String msg = read_string("out.txt") }
  runtime { cpu: 1 memory: "1 GB" }
}
EOF
java -Dconfig.file=/dev/null -jar "/jetstream2/scratch/main/jobs/79144340/inputs/dataset_2ac0cb03-4620-4750-91ad-0e47d0ba0137.dat" run tiny.wdl > cromwell.stdout 2> cromwell.stderr
find cromwell-executions -maxdepth 6 -type f | sort > files.txt 2>/dev/null
{
  echo '--- stdout tail ---'
  tail -80 cromwell.stdout
  echo '--- stderr ---'
  sed -n '1,160p' cromwell.stderr
  echo '--- files ---'
  sed -n '1,120p' files.txt
} > probe.txt
exit 0
